ALTER TABLE public.lancamentos ADD COLUMN data_lancamento date;
UPDATE public.lancamentos SET data_lancamento = (mes || '-01')::date WHERE data_lancamento IS NULL AND mes ~ '^[0-9]{4}-(0[1-9]|1[0-2])$';
CREATE OR REPLACE FUNCTION public.financeiro_sync_data() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.data_lancamento IS NOT NULL THEN NEW.mes := to_char(NEW.data_lancamento,'YYYY-MM'); ELSE NEW.data_lancamento := (NEW.mes || '-01')::date; END IF; RETURN NEW; END $$;
CREATE TRIGGER financeiro_sync_data BEFORE INSERT OR UPDATE OF data_lancamento ON public.lancamentos FOR EACH ROW EXECUTE FUNCTION public.financeiro_sync_data();
CREATE INDEX lancamentos_data ON public.lancamentos(data_lancamento);
CREATE OR REPLACE FUNCTION public.financeiro_nome_chave(n text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT lower(translate(regexp_replace(trim(n),'\s+',' ','g'),'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC')); $$;
CREATE TABLE public.financeiro_grupos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL,tipo text NOT NULL DEFAULT 'Ambos' CHECK(tipo IN ('Entrada','Saída','Ambos')),ativo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.financeiro_grupos TO authenticated; GRANT ALL ON public.financeiro_grupos TO service_role; ALTER TABLE public.financeiro_grupos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner finance groups" ON public.financeiro_grupos FOR ALL TO authenticated USING(public.has_owner_access()) WITH CHECK(public.has_owner_access());
CREATE UNIQUE INDEX financeiro_grupos_nome ON public.financeiro_grupos(public.financeiro_nome_chave(nome));
CREATE TABLE public.financeiro_categorias(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL,grupo_id uuid REFERENCES public.financeiro_grupos(id),tipo text NOT NULL DEFAULT 'Ambos' CHECK(tipo IN ('Entrada','Saída','Ambos')),ativo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.financeiro_categorias TO authenticated; GRANT ALL ON public.financeiro_categorias TO service_role; ALTER TABLE public.financeiro_categorias ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner finance categories" ON public.financeiro_categorias FOR ALL TO authenticated USING(public.has_owner_access()) WITH CHECK(public.has_owner_access());
CREATE UNIQUE INDEX financeiro_categorias_nome ON public.financeiro_categorias(public.financeiro_nome_chave(nome));
INSERT INTO public.financeiro_grupos(nome,tipo) SELECT min(regexp_replace(trim(grupo),'\s+',' ','g')),CASE WHEN count(DISTINCT tipo)>1 THEN 'Ambos' WHEN min(tipo)='entrada' THEN 'Entrada' ELSE 'Saída' END FROM public.lancamentos WHERE trim(grupo)<>'' GROUP BY public.financeiro_nome_chave(grupo);
WITH categorias AS (SELECT public.financeiro_nome_chave(categoria) AS chave,min(regexp_replace(trim(categoria),'\s+',' ','g')) AS nome,CASE WHEN count(DISTINCT tipo)>1 THEN 'Ambos' WHEN min(tipo)='entrada' THEN 'Entrada' ELSE 'Saída' END AS tipo FROM public.lancamentos WHERE trim(categoria)<>'' GROUP BY public.financeiro_nome_chave(categoria))
INSERT INTO public.financeiro_categorias(nome,tipo,grupo_id) SELECT c.nome,c.tipo,(SELECT g.id FROM public.financeiro_grupos g JOIN public.lancamentos x ON public.financeiro_nome_chave(x.grupo)=public.financeiro_nome_chave(g.nome) WHERE public.financeiro_nome_chave(x.categoria)=c.chave GROUP BY g.id ORDER BY count(*) DESC,g.id LIMIT 1) FROM categorias c;
CREATE OR REPLACE FUNCTION public.financeiro_item_proteger() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE campo text; usados bigint; BEGIN campo:=CASE WHEN TG_TABLE_NAME='financeiro_grupos' THEN 'grupo' ELSE 'categoria' END; IF TG_OP='DELETE' THEN EXECUTE format('SELECT count(*) FROM public.lancamentos WHERE public.financeiro_nome_chave(%I)=public.financeiro_nome_chave($1)',campo) INTO usados USING OLD.nome; IF usados>0 THEN RAISE EXCEPTION 'Item utilizado em % lançamentos. Desative em vez de excluir.',usados; END IF; RETURN OLD; END IF; NEW.nome:=regexp_replace(trim(NEW.nome),'\s+',' ','g'); IF NEW.nome='' THEN RAISE EXCEPTION 'Informe o nome.'; END IF; IF TG_OP='UPDATE' AND NEW.nome IS DISTINCT FROM OLD.nome THEN EXECUTE format('UPDATE public.lancamentos SET %I=$1 WHERE public.financeiro_nome_chave(%I)=public.financeiro_nome_chave($2)',campo,campo) USING NEW.nome,OLD.nome; END IF; RETURN NEW; END $$;
CREATE TRIGGER financeiro_grupos_proteger BEFORE INSERT OR UPDATE OR DELETE ON public.financeiro_grupos FOR EACH ROW EXECUTE FUNCTION public.financeiro_item_proteger();
CREATE TRIGGER financeiro_categorias_proteger BEFORE INSERT OR UPDATE OR DELETE ON public.financeiro_categorias FOR EACH ROW EXECUTE FUNCTION public.financeiro_item_proteger();
CREATE OR REPLACE FUNCTION public.financeiro_mesclar_categorias(origem_id uuid,destino_id uuid) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE origem_nome text; destino_nome text; afetados integer; BEGIN IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; IF origem_id=destino_id THEN RAISE EXCEPTION 'Escolha categorias diferentes.'; END IF; SELECT nome INTO origem_nome FROM public.financeiro_categorias WHERE id=origem_id FOR UPDATE; SELECT nome INTO destino_nome FROM public.financeiro_categorias WHERE id=destino_id FOR UPDATE; IF origem_nome IS NULL OR destino_nome IS NULL THEN RAISE EXCEPTION 'Categoria não encontrada.'; END IF; UPDATE public.lancamentos SET categoria=destino_nome WHERE public.financeiro_nome_chave(categoria)=public.financeiro_nome_chave(origem_nome); GET DIAGNOSTICS afetados=ROW_COUNT; UPDATE public.financeiro_categorias SET ativo=false WHERE id=origem_id; RETURN afetados; END $$;
REVOKE ALL ON FUNCTION public.financeiro_mesclar_categorias(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_mesclar_categorias(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.financeiro_sync_data(),public.financeiro_item_proteger() FROM PUBLIC,anon,authenticated;